    for (var a = 0; a < 8; a++) {
        if (mcp_devices[a].enabled) {
            var mcp_device = mcp_devices[a].name;
            var inputs = [];
            for (var i = 1; i < 9; i++) {
                var input = true;
                if (mcp_devices[a].value_A === "Input") {
                    for (var y = 0; y < msg.payload.length; y++) {
                        if (msg.payload[y].device === mcp_device && msg.payload[y].entry === "channel_" + i) {
                            input = false;
                        }
                    }
                    if (input) {
                        inputs.push({
                            "name": "channel_" + i,
                            "value": "channel_" + i,
                            "disabled": false,
                        })
                    }
                    else {
                        inputs.push({
                            "name": "channel_" + i,
                            "value": "channel_" + i,
                            "disabled": true,
                        })
                    }
                }
            }
            for (var i = 9; i < 17; i++) {
                var input = true;
                if (mcp_devices[a].value_B === "Input") {
                    for (var y = 0; y < msg.payload.length; y++) {
                        if (msg.payload[y].device === mcp_device && msg.payload[y].entry === "channel_" + i) {
